set -e
cd /home/ubuntu/testlogon
TS=$(date +%s)
echo "== baseline md5 =="
md5sum app/routers/subscription_server.py app/services/subscription_renewal.py
BS=$(md5sum app/routers/subscription_server.py | cut -d" " -f1)
BR=$(md5sum app/services/subscription_renewal.py | cut -d" " -f1)
if [ "$BS" != "428ea00dd3fffae29a4b196f5cffcce9" ] || [ "$BR" != "13a145b476fa6875439387cead15c1f8" ]; then echo BASELINE_MISMATCH_ABORT; exit 3; fi
cp app/routers/subscription_server.py app/routers/subscription_server.py.bak_subx_$TS
cp app/services/subscription_renewal.py app/services/subscription_renewal.py.bak_subx_$TS
cat > /tmp/subx1_server.b64 <<'EOFB64S'

EOFB64S
cat > /tmp/subx1_renewal.b64 <<'EOFB64R'

EOFB64R
base64 -d /tmp/subx1_server.b64 > /tmp/subx1_server.patch
base64 -d /tmp/subx1_renewal.b64 > /tmp/subx1_renewal.patch
patch app/routers/subscription_server.py < /tmp/subx1_server.patch
patch app/services/subscription_renewal.py < /tmp/subx1_renewal.patch
echo "== post-patch md5 =="
md5sum app/routers/subscription_server.py app/services/subscription_renewal.py
AS=$(md5sum app/routers/subscription_server.py | cut -d" " -f1)
AR=$(md5sum app/services/subscription_renewal.py | cut -d" " -f1)
if [ "$AS" != "a62ec6b2658ffb80c74d2bee36315afa" ] || [ "$AR" != "ec6600652ca37c757d0f0a2c714a7cd8" ]; then echo POSTPATCH_MISMATCH_RESTORING; cp app/routers/subscription_server.py.bak_subx_$TS app/routers/subscription_server.py; cp app/services/subscription_renewal.py.bak_subx_$TS app/services/subscription_renewal.py; exit 4; fi
python3 -c "import ast; ast.parse(open(\"app/routers/subscription_server.py\").read()); ast.parse(open(\"app/services/subscription_renewal.py\").read()); print(\"AST_OK\")"
chown ubuntu:ubuntu app/routers/subscription_server.py app/services/subscription_renewal.py
sudo -u ubuntu bash /home/ubuntu/restart_backend.sh
echo BACKUP_TS $TS
